    "content": "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>LBASE 兼容性诊断</title>\n<style>\n  body {\n    font-family: -apple-system, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n    background: #151a23;\n    color: #f2f5f9;\n    padding: 20px;\n    line-height: 1.7;\n    font-size: 15px;\n  }\n  h1 { font-size: 20px; margin-bottom: 8px; }\n  .sub { color: #93a1b5; font-size: 13px; margin-bottom: 20px; }\n  .item {\n    padding: 10px 12px;\n    margin-bottom: 8px;\n    border-radius: 6px;\n    background: #212936;\n    border-left: 3px solid #35404f;\n  }\n  .ok { border-left-color: #3ddcab; }\n  .bad { border-left-color: #f07070; }\n  .name { font-weight: 600; }\n  .val { color: #b6c2d2; font-family: monospace; font-size: 13px; margin-top: 2px; }\n  .summary { margin-top: 24px; padding: 14px; border-radius: 8px; background: #2563eb; }\n  pre { background: #0e1117; padding: 12px; border-radius: 6px; overflow-x: auto; font-size: 13px; }\n</style>\n</head>\n<body>\n<h1>LBASE 兼容性诊断</h1>\n<p class=\"sub\">这个页面会检查你的浏览器支持哪些特性。把结果截图或复制给我。</p>\n<div id=\"out\"></div>\n\n<script>\n(function () {\n  var out = document.getElementById('out');\n  var results = [];\n  var fails = 0;\n\n  function test(name, fn) {\n    var ok = false, val = '';\n    try {\n      val = fn();\n      ok = true;\n    } catch (e) {\n      val = '❌ ' + e.message;\n      ok = false;\n      fails++;\n    }\n    results.push({ name: name, ok: ok, val: String(val) });\n  }\n\n  // 浏览器信息\n  var ua = navigator.userAgent;\n  test('浏览器 UA', function () { return ua; });\n  test('window.fetch', function () { return typeof fetch; });\n  test('Promise', function () { return typeof Promise; });\n  test('async / await', function () { return eval('(async function(){return \"支持\"})()') ? '支持' : '不支持'; });\n  test('可选链 ?.', function () { return eval('({a:{b:1}}).a?.b'); });\n  test('空值合并 ??', function () { return eval('null ?? \"支持\"'); });\n  test('模板字符串', function () { return eval('`a${1}b`'); });\n  test('箭头函数', function () { return eval('(x=>x+1)(1)'); });\n  test('展开运算符', function () { return eval('[...[1,2],3].join(\",\")'); });\n  test('Array.flat', function () { return [1,[2]].flat().join(','); });\n  test('replaceChildren', function () {\n    var d = document.createElement('div');\n    if (typeof d.replaceChildren !== 'function') throw new Error('不支持');\n    return '支持';\n  });\n  test('AbortController', function () { return typeof AbortController; });\n  test('localStorage', function () {\n    localStorage.setItem('__t', '1');\n    var v = localStorage.getItem('__t');\n    localStorage.removeItem('__t');\n    return v;\n  });\n  test('CSS 变量', function () {\n    return window.CSS && CSS.supports && CSS.supports('color', 'var(--x)') ? '支持' : '不支持';\n  });\n  test('CSS grid', function () {\n    return window.CSS && CSS.supports && CSS.supports('display', 'grid') ? '支持' : '不支持';\n  });\n  test('CSS dvh 单位', function () {\n    if (!window.CSS || !CSS.supports) return '无法检测';\n    return CSS.supports('height', '100dvh') ? '支持' : '❌ 不支持';\n  });\n  test('backdrop-filter', function () {\n    if (!window.CSS || !CSS.supports) return '无法检测';\n    return CSS.supports('backdrop-filter', 'blur(4px)') ? '支持' : '不支持';\n  });\n  test('CSS clamp()', function () {\n    if (!window.CSS || !CSS.supports) return '无法检测';\n    return CSS.supports('width', 'clamp(1px,2vw,3px)') ? '支持' : '不支持';\n  });\n  test('navigator.clipboard', function () { return navigator.clipboard ? '支持' : '❌ 不支持'; });\n  test('script type=module', function () {\n    var s = document.createElement('script');\n    s.type = 'module';\n    return s.type === 'module' ? '支持' : '❌ 不支持';\n  });\n\n  // 实际 fetch 测试\n  function render() {\n    var html = '';\n    results.forEach(function (r) {\n      var cls = r.ok ? 'ok' : 'bad';\n      var badge = r.ok ? '✅' : '❌';\n      html += '<div class=\"item ' + cls + '\">' +\n        '<div class=\"name\">' + badge + ' ' + r.name + '</div>' +\n        '<div class=\"val\">' + r.val + '</div>' +\n        '</div>';\n    });\n    out.innerHTML = html;\n\n    var sum = document.createElement('div');\n    sum.className = 'summary';\n    if (fails === 0) {\n      sum.innerHTML = '<b>全部通过</b>。如果 LBASE 还是黑屏，请把这段 UA 发给我：<br><code>' + ua + '</code>';\n    } else {\n      sum.innerHTML = '<b>' + fails + ' 项不支持</b>。这些是导致黑屏的原因，我会改进代码。';\n    }\n    out.appendChild(sum);\n\n    // 最后测真实 fetch\n    var fdiv = document.createElement('div');\n    fdiv.className = 'item';\n    fdiv.innerHTML = '<div class=\"name\">⏳ 测试读取 LBASE 页面…</div>';\n    out.appendChild(fdiv);\n    fetch('/api/health')\n      .then(function (r) { return r.json(); })\n      .then(function (j) {\n        fdiv.className = 'item ok';\n        fdiv.innerHTML = '<div class=\"name\">✅ 能连上 LBASE 后端</div><div class=\"val\">' +\n          JSON.stringify(j).slice(0, 120) + '</div>';\n      })\n      .catch(function (e) {\n        fdiv.className = 'item bad';\n        fdiv.innerHTML = '<div class=\"name\">❌ 连不上 LBASE 后端</div><div class=\"val\">' + e.message + '</div>';\n      });\n\n    // 测 JS 模块能否加载\n    var mdiv = document.createElement('div');\n    mdiv.className = 'item';\n    mdiv.innerHTML = '<div class=\"name\">⏳ 测试加载界面脚本…</div>';\n    out.appendChild(mdiv);\n    fetch('/ui/app.js')\n      .then(function (r) { return r.text(); })\n      .then(function (t) {\n        mdiv.className = 'item ok';\n        mdiv.innerHTML = '<div class=\"name\">✅ 界面脚本文件能下载</div><div class=\"val\">' +\n          Math.round(t.length / 1024) + ' KB</div>';\n      })\n      .catch(function (e) {\n        mdiv.className = 'item bad';\n        mdiv.innerHTML = '<div class=\"name\">❌ 界面脚本下载失败</div><div class=\"val\">' + e.message + '</div>';\n      });\n  }\n\n  render();\n})();\n</script>\n</body>\n</html>\n"
