    "content": "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>溯源 · Buddy Trace</title>\n<meta name=\"description\" content=\"WorkBuddy 记忆的延伸 —— 项目丝滑交接，历史随时溯源。\">\n<link rel=\"icon\" type=\"image/x-icon\" href=\"/favicon.ico\">\n<link rel=\"apple-touch-icon\" href=\"/img/logo-mark-128.png\">\n<link rel=\"stylesheet\" href=\"/ui/app.css?v=__VER__\">\n</head>\n<body>\n\n<div class=\"shell\">\n\n  <!-- 顶栏：品牌 + 统计 -->\n  <header class=\"topbar\">\n    <a class=\"brand\" href=\"#/\" title=\"溯源 · Buddy Trace\">\n      <img class=\"brand-mark\" src=\"/img/logo-mark-64.png\" alt=\"\" width=\"26\" height=\"26\">\n      <span class=\"brand-word\">溯源</span>\n      <span class=\"brand-dot\">·</span>\n      <span class=\"brand-en\">Buddy Trace</span>\n    </a>\n    <div class=\"topbar-right\" id=\"topbarRight\"></div>\n  </header>\n\n  <div class=\"body-row\">\n\n    <!-- 左侧菜单（分组） -->\n    <aside class=\"sider\" id=\"sider\"></aside>\n\n    <!-- 右侧主区 -->\n    <div class=\"content\">\n      <div class=\"tabbar\" id=\"tabbar\"></div>\n      <main id=\"app\" class=\"page-frame\">\n        <div class=\"boot-hint\">\n          <p>正在加载…</p>\n          <p class=\"boot-hint-sub\">如果一直停在这里，请按 Ctrl+F5 强制刷新</p>\n        </div>\n      </main>\n    </div>\n\n  </div>\n</div>\n\n<noscript>\n  <div style=\"padding:48px 24px;text-align:center;color:#4a5856;font-family:system-ui,sans-serif\">\n    <p style=\"font-size:15px\">本页需要 JavaScript 才能运行</p>\n    <p style=\"font-size:13px;margin-top:12px\">请在你的浏览器里启用 JavaScript，然后刷新页面。</p>\n  </div>\n</noscript>\n\n<!-- 对话框 -->\n<div class=\"modal-mask\" id=\"modalMask\" hidden>\n  <div class=\"modal\" id=\"modal\" role=\"dialog\" aria-modal=\"true\"></div>\n</div>\n\n<div class=\"toast-wrap\" id=\"toastWrap\"></div>\n\n<script type=\"module\" src=\"/ui/app.js?v=__VER__\"></script>\n</body>\n</html>\n"
